import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../../contexts/AuthContext';
import { eredesService } from '../../services/eredesService';
import {
  Card,
  Button,
  MetricCard,
  Chart,
  StatusIndicator,
  LoadingSpinner
} from '../../components';
import './Dashboard.styles.css';

const Dashboard = () => {
  const navigate = useNavigate();
  const { isAuthenticated, user } = useAuth();

  const [dashboardData, setDashboardData] = useState({
    recentSimulations: [],
    quickStats: {},
    loading: true,
    error: null
  });

  const [recentActivity, setRecentActivity] = useState([]);

  useEffect(() => {
    loadDashboardData();
  }, [isAuthenticated]);

  const loadDashboardData = async () => {
    if (!isAuthenticated) {
      setDashboardData(prev => ({ ...prev, loading: false }));
      return;
    }

    try {
      setDashboardData(prev => ({ ...prev, loading: true, error: null }));

      // Load recent simulations and stats
      const [simulationsResponse, statsResponse] = await Promise.all([
        eredesService.getRecentSimulations(5),
        eredesService.getDashboardStats()
      ]);

      setDashboardData({
        recentSimulations: simulationsResponse.simulations || [],
        quickStats: statsResponse.stats || {},
        loading: false,
        error: null
      });

      // Load recent activity
      const activityResponse = await eredesService.getRecentActivity();
      setRecentActivity(activityResponse.activities || []);

    } catch (error) {
      console.error('Failed to load dashboard data:', error);
      setDashboardData(prev => ({
        ...prev,
        loading: false,
        error: error.message || 'Erro ao carregar dados do dashboard'
      }));
    }
  };

  const formatDate = (dateString) => {
    return new Date(dateString).toLocaleDateString('pt-PT', {
      day: 'numeric',
      month: 'short',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  const formatCurrency = (value) => {
    return new Intl.NumberFormat('pt-PT', {
      style: 'currency',
      currency: 'EUR'
    }).format(value || 0);
  };

  const getStatusColor = (status) => {
    switch (status) {
      case 'completed': return '#4caf50';
      case 'running': return '#ff9800';
      case 'failed': return '#f44336';
      default: return '#757575';
    }
  };

  const getStatusLabel = (status) => {
    switch (status) {
      case 'completed': return 'Conclu�da';
      case 'running': return 'Em execu��o';
      case 'failed': return 'Falhou';
      default: return 'Desconhecido';
    }
  };

  if (dashboardData.loading) {
    return (
      <div className="dashboard-loading">
        <LoadingSpinner size="lg" />
        <p>Carregando dashboard...</p>
      </div>
    );
  }

  if (dashboardData.error) {
    return (
      <div className="dashboard-error">
        <Card glass padding="xl" className="error-card">
          <div className="error-content">
            <div className="error-icon">L</div>
            <h2>Erro no Dashboard</h2>
            <p>{dashboardData.error}</p>
            <Button onClick={loadDashboardData} variant="primary">
              Tentar Novamente
            </Button>
          </div>
        </Card>
      </div>
    );
  }

  return (
    <div className="dashboard">
      <div className="page-header">
        <div className="header-content">
          <h1 className="page-title gradient-text">
            � Dashboard E-REDES
          </h1>
          <p className="page-subtitle">
            An�lise inteligente do seu consumo energ�tico
          </p>
        </div>

        <div className="header-actions">
          <Button
            onClick={() => navigate('/simulation')}
            variant="primary"
            size="lg"
          >
            =� Nova Simula��o
          </Button>
        </div>
      </div>

      <div className="dashboard-content">
        {/* Welcome Section */}
        <div className="welcome-section">
          <Card glass padding="lg" className="welcome-card">
            <div className="welcome-content">
              <div className="welcome-text">
                <h2>Bem-vindo ao E-REDES Bot</h2>
                <p>
                  {isAuthenticated
                    ? `Ol� ${user?.name || 'Utilizador'}! Pronto para analisar o seu consumo?`
                    : 'Fa�a login para aceder aos seus dados de consumo.'
                  }
                </p>
              </div>

              <div className="auth-status">
                <StatusIndicator
                  status={isAuthenticated ? 'success' : 'waiting'}
                  message={isAuthenticated
                    ? 'Conta conectada'
                    : 'Fa�a login'
                  }
                />
              </div>
            </div>
          </Card>
        </div>

        {isAuthenticated ? (
          <>
            {/* Quick Stats */}
            {Object.keys(dashboardData.quickStats).length > 0 && (
              <div className="stats-section">
                <h2 className="section-title">Estat�sticas R�pidas</h2>
                <div className="stats-grid">
                  <MetricCard
                    title="Total de Simula��es"
                    value={dashboardData.quickStats.totalSimulations || 0}
                    icon="=�"
                    trend={dashboardData.quickStats.simulationTrend}
                  />

                  <MetricCard
                    title="Consumo M�dio"
                    value={`${dashboardData.quickStats.avgConsumption || 0} kWh`}
                    icon="�"
                    subtitle="Por dia"
                  />

                  <MetricCard
                    title="Custo Estimado"
                    value={formatCurrency(dashboardData.quickStats.estimatedCost)}
                    icon="=�"
                    subtitle="�ltimo per�odo"
                  />

                  <MetricCard
                    title="Efici�ncia"
                    value={`${dashboardData.quickStats.efficiency || 0}%`}
                    icon="=�"
                    trend={dashboardData.quickStats.efficiencyTrend}
                  />
                </div>
              </div>
            )}

            {/* Recent Simulations */}
            <div className="simulations-section">
              <div className="section-header">
                <h2 className="section-title">Simula��es Recentes</h2>
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={() => navigate('/simulation')}
                >
                  Ver Todas
                </Button>
              </div>

              {dashboardData.recentSimulations.length === 0 ? (
                <Card glass padding="xl" className="empty-state">
                  <div className="empty-content">
                    <div className="empty-icon">=�</div>
                    <h3>Sem simula��es ainda</h3>
                    <p>Comece a primeira simula��o para analisar o seu consumo</p>
                    <Button
                      onClick={() => navigate('/simulation')}
                      variant="primary"
                    >
                      Criar Primeira Simula��o
                    </Button>
                  </div>
                </Card>
              ) : (
                <div className="simulations-grid">
                  {dashboardData.recentSimulations.map((simulation) => (
                    <Card
                      key={simulation.id}
                      glass
                      padding="lg"
                      className="simulation-card"
                      onClick={() => navigate(`/results/${simulation.id}`)}
                    >
                      <div className="simulation-header">
                        <div className="simulation-info">
                          <h3 className="simulation-title">
                            {simulation.cpe || 'Simula��o'}
                          </h3>
                          <p className="simulation-date">
                            {formatDate(simulation.createdAt)}
                          </p>
                        </div>

                        <StatusIndicator
                          status={simulation.status === 'completed' ? 'success' :
                                 simulation.status === 'running' ? 'loading' : 'error'}
                          message={getStatusLabel(simulation.status)}
                          size="sm"
                        />
                      </div>

                      {simulation.results && (
                        <div className="simulation-results">
                          <div className="result-item">
                            <span className="result-label">Consumo:</span>
                            <span className="result-value">
                              {simulation.results.totalConsumption} kWh
                            </span>
                          </div>

                          <div className="result-item">
                            <span className="result-label">Custo:</span>
                            <span className="result-value">
                              {formatCurrency(simulation.results.estimatedCost)}
                            </span>
                          </div>

                          <div className="result-item">
                            <span className="result-label">Per�odo:</span>
                            <span className="result-value">
                              {new Date(simulation.startDate).toLocaleDateString('pt-PT')} -
                              {new Date(simulation.endDate).toLocaleDateString('pt-PT')}
                            </span>
                          </div>
                        </div>
                      )}

                      <div className="simulation-actions">
                        <Button
                          size="sm"
                          variant="ghost"
                          onClick={(e) => {
                            e.stopPropagation();
                            navigate(`/results/${simulation.id}`);
                          }}
                        >
                          Ver Detalhes
                        </Button>
                      </div>
                    </Card>
                  ))}
                </div>
              )}
            </div>

            {/* Recent Activity */}
            {recentActivity.length > 0 && (
              <div className="activity-section">
                <h2 className="section-title">Atividade Recente</h2>
                <Card glass padding="lg" className="activity-card">
                  <div className="activity-list">
                    {recentActivity.map((activity, index) => (
                      <div key={index} className="activity-item">
                        <div className="activity-icon">
                          {activity.type === 'simulation' && '=,'}
                          {activity.type === 'export' && '=�'}
                          {activity.type === 'login' && '='}
                        </div>

                        <div className="activity-content">
                          <p className="activity-description">
                            {activity.description}
                          </p>
                          <span className="activity-time">
                            {formatDate(activity.timestamp)}
                          </span>
                        </div>
                      </div>
                    ))}
                  </div>
                </Card>
              </div>
            )}
          </>
        ) : (
          /* Not Authenticated */
          <div className="not-authenticated">
            <Card glass padding="xl" className="auth-prompt">
              <div className="auth-content">
                <div className="auth-icon">=</div>
                <h2>Acesso Necess�rio</h2>
                <p>
                  Para ver o seu dashboard personalizado e criar simula��es,
                  precisa de fazer login na sua conta E-REDES.
                </p>

                <div className="auth-features">
                  <div className="feature-item">
                    <span className="feature-icon">=�</span>
                    <span className="feature-text">Dados reais de consumo</span>
                  </div>
                  <div className="feature-item">
                    <span className="feature-icon">=�</span>
                    <span className="feature-text">Simula��es de custos</span>
                  </div>
                  <div className="feature-item">
                    <span className="feature-icon">=�</span>
                    <span className="feature-text">An�lises detalhadas</span>
                  </div>
                  <div className="feature-item">
                    <span className="feature-icon">=�</span>
                    <span className="feature-text">Exporta��o profissional</span>
                  </div>
                </div>

                <Button
                  onClick={() => navigate('/simulation')}
                  variant="primary"
                  size="lg"
                >
                  Come�ar Simula��o
                </Button>
              </div>
            </Card>
          </div>
        )}
      </div>
    </div>
  );
};

export default Dashboard;
